3	use serde_json::{json, Map, Value};
4	
5	const MAX_DEPTH: usize = 64;
6	
7	/// Keywords Gemini's schema validator rejects outright.
8	const STRIP: &[&str] = &[
9	    "$schema",
10	    "$id",
11	    "$anchor",
12	    "$comment",
13	    "additionalProperties",
14	    "unevaluatedProperties",
15	    "patternProperties",
16	    "examples",
17	    "default",
18	];
19	
20	/// Rewrite `schema` into Gemini's OpenAPI-3.0 subset.
21	///
22	/// Inlines `$ref`, strips unsupported keywords, and preserves combinator
23	/// meaning (`oneOf`→`anyOf`, `[T,null]`→`nullable:true`, `const`→`enum:[v]`).
24	pub(crate) fn sanitize_schema(schema: &Value) -> Value {
25	    let defs = collect_defs(schema);
26	    rewrite(schema, &defs, 0, &mut Vec::new())
27	}
28	
29	fn collect_defs(root: &Value) -> Map<String, Value> {
30	    let mut out = Map::new();
31	    for key in ["$defs", "definitions"] {
32	        if let Some(Value::Object(m)) = root.get(key) {
33	            for (k, v) in m {
34	                out.insert(k.clone(), v.clone());
35	            }
36	        }
37	    }
38	    out
39	}
40	
41	fn rewrite(node: &Value, defs: &Map<String, Value>, depth: usize, seen: &mut Vec<String>) -> Value {
42	    if depth > MAX_DEPTH {
43	        return json!({ "type": "object" });
44	    }
45	    let Value::Object(obj) = node else {
46	        return node.clone();
47	    };
48	
49	    // 1. $ref inlining with cycle guard.
50	    if let Some(Value::String(r)) = obj.get("$ref") {
51	        let name = r.rsplit('/').next().unwrap_or_default().to_owned();
52	        if seen.contains(&name) {
53	            return json!({ "type": "object" });
54	        }
55	        if let Some(target) = defs.get(&name) {
56	            seen.push(name);
57	            let out = rewrite(target, defs, depth + 1, seen);
58	            seen.pop();
59	            return out;
60	        }
61	        return json!({ "type": "object" });
62	    }
63	
64	    let mut out = Map::new();
65	    for (k, v) in obj {
66	        if STRIP.contains(&k.as_str()) || k == "$defs" || k == "definitions" {
67	            continue;
68	        }
69	        match k.as_str() {
70	            // 3. const -> enum:[v]
71	            "const" => {
72	                out.insert("enum".into(), json!([v.clone()]));
73	            }
74	            // type: [T, "null"] -> T + nullable:true;
75	            // type: [A, B, ...] (multiple non-null) -> anyOf to preserve every type.

